:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --available: #533483;
  --taken: #2b2b3b;
  --selected: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px 20px;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 16px;
  letter-spacing: 1px;
}

.screen-label {
  font-size: 0.875rem;
  letter-spacing: 4px;
  color: var(--accent);
  margin-bottom: 8px;
}

.screen {
  height: 8px;
  background: linear-gradient(to bottom, var(--accent), transparent);
  border-radius: 4px;
  margin-bottom: 24px;
  opacity: 0.6;
}

.seat-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 6px;
  margin-bottom: 24px;
}

.seat {
  aspect-ratio: 1;
  border: none;
  border-radius: 8px;
  background: var(--available);
  color: var(--text);
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  min-width: 0;
}

.seat:hover:not(.taken) {
  background: #6a4c93;
}

.seat:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.seat:active:not(.taken) {
  transform: scale(0.92);
}

.seat.taken {
  background: var(--taken);
  cursor: not-allowed;
  color: #555;
}

.seat.selected {
  background: var(--selected);
  color: #fff;
}

.seat.selected:hover {
  background: #f05a73;
}

.summary {
  margin-bottom: 20px;
  font-size: 1rem;
  line-height: 1.6;
}

#selected-seats {
  color: var(--accent);
  font-weight: 600;
  min-height: 1.6em;
}

#total-price {
  font-size: 1.25rem;
  font-weight: 700;
}

.reset-btn {
  background: var(--primary);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.reset-btn:hover {
  background: var(--accent);
}

.reset-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.reset-btn:active {
  transform: scale(0.96);
}

@media (max-width: 400px) {
  .container {
    padding: 16px 12px;
  }
  .seat-grid {
    gap: 4px;
  }
  .seat {
    font-size: 0.6rem;
    border-radius: 6px;
  }
  h1 {
    font-size: 1.5rem;
  }
}

const ROWS = 5;
const COLS = 8;
const PRICE_PER_SEAT = 9;
const ROW_LABELS = ['A', 'B', 'C', 'D', 'E'];

// Pre-taken seats (row index, col index)
const TAKEN = [
  [0, 2], [0, 5],
  [1, 1], [1, 6],
  [2, 3], [2, 4],
  [3, 0], [3, 7],
  [4, 2], [4, 5]
];

const seatGrid = document.getElementById('seat-grid');
const selectedSeatsEl = document.getElementById('selected-seats');
const totalPriceEl = document.getElementById('total-price');
const resetBtn = document.getElementById('reset-btn');

const selectedSeats = new Set();

function isTaken(row, col) {
  return TAKEN.some(([r, c]) => r === row && c === col);
}

function seatId(row, col) {
  return `${ROW_LABELS[row]}${col + 1}`;
}

function createSeat(row, col) {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'seat';
  btn.textContent = col + 1;
  btn.dataset.row = row;
  btn.dataset.col = col;
  btn.setAttribute('role', 'gridcell');

  const id = seatId(row, col);

  if (isTaken(row, col)) {
    btn.classList.add('taken');
    btn.disabled = true;
    btn.setAttribute('aria-label', `Seat ${id}, taken`);
  } else {
    btn.setAttribute('aria-label', `Seat ${id}, available`);
    btn.setAttribute('aria-pressed', 'false');
    btn.addEventListener('click', () => toggleSeat(btn, id));
  }

  return btn;
}

function toggleSeat(btn, id) {
  if (selectedSeats.has(id)) {
    selectedSeats.delete(id);
    btn.classList.remove('selected');
    btn.setAttribute('aria-pressed', 'false');
  } else {
    selectedSeats.add(id);
    btn.classList.add('selected');
    btn.setAttribute('aria-pressed', 'true');
  }
  updateSummary();
}

function updateSummary() {
  const sorted = [...selectedSeats].sort();
  if (sorted.length === 0) {
    selectedSeatsEl.textContent = 'No seats selected';
  } else {
    selectedSeatsEl.textContent = `Selected: ${sorted.join(', ')}`;
  }
  totalPriceEl.textContent = `Total: $${sorted.length * PRICE_PER_SEAT}`;
}

function buildGrid() {
  seatGrid.innerHTML = '';
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      seatGrid.appendChild(createSeat(r, c));
    }
  }
}

resetBtn.addEventListener('click', () => {
  selectedSeats.clear();
  document.querySelectorAll('.seat.selected').forEach((btn) => {
    btn.classList.remove('selected');
    btn.setAttribute('aria-pressed', 'false');
  });
  updateSummary();
});

buildGrid();
updateSummary();
